package org.apache.commons.lang3.time;

import org.junit.Test;
import org.junit.Assert;
import java.util.Calendar;
import java.util.GregorianCalendar;
import java.util.TimeZone;

public class AgentBRT_Lang_38_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        // Set up a FastDateFormat instance with a forced time zone
        FastDateFormat fastDateFormat = FastDateFormat.getInstance("yyyy-MM-dd HH:mm:ss", TimeZone.getTimeZone("GMT"));

        // Create a calendar instance with a different time zone
        Calendar calendar = new GregorianCalendar(TimeZone.getTimeZone("PST"));
        calendar.set(2023, Calendar.JANUARY, 1, 12, 0, 0); // 2023-01-01 12:00:00 PST

        // Format the calendar
        StringBuffer formattedDate = fastDateFormat.format(calendar, new StringBuffer());

        // The expected result should be in GMT
        String expected = "2023-01-01 20:00:00"; // 12:00 PST is 20:00 GMT

        // Assert that the formatted date is as expected
        Assert.assertEquals("Formatted date should be in GMT", expected, formattedDate.toString());
    }
}

